      "issues": [
        {
          "dimension": "consistency",
          "detail": "synonyms 中“想不开”也常指一时纠结、无法释怀，并不一定指自杀，作为检索别名会误命中，应删除。"
        }
      ],
      "reason": "压力联想支持自我负向，安全提示适当，但“想不开”不是可靠的自杀同义词。"
    },
